#define main legacy_main
#include "../streamPriority-cuda/main.cu"
#undef main
#include <fstream>
#include <iostream>
#include <iomanip>
#include <tuple>
struct Case{int n,batches,seed,mode;std::vector<std::vector<float>>init,ref;float*d[5];};
int main(){int lo,hi;GPU_CHECK(cudaDeviceGetStreamPriorityRange(&lo,&hi));std::cout<<"STUDY_PRIORITIES least="<<lo<<" greatest="<<hi<<std::endl;cudaStream_t train,prefetch;GPU_CHECK(cudaStreamCreateWithPriority(&train,cudaStreamNonBlocking,hi));GPU_CHECK(cudaStreamCreateWithPriority(&prefetch,cudaStreamNonBlocking,lo));int tp,pp;GPU_CHECK(cudaStreamGetPriority(train,&tp));GPU_CHECK(cudaStreamGetPriority(prefetch,&pp));std::cout<<"STUDY_ACTUAL_PRIORITIES train="<<tp<<" prefetch="<<pp<<std::endl;std::vector<Case>cases;std::vector<float>prefix;for(auto spec:std::vector<std::vector<int>>{{1025,4,0},{8193,5,1}})for(int mode:{0,1}){Case c;c.n=spec[0];c.batches=spec[1];c.seed=spec[2];c.mode=mode;c.init.assign(5,std::vector<float>(c.n,0));for(int i=0;i<c.n;i++){c.init[1][i]=c.seed==0?1:float(i%17-8)/8;c.init[2][i]=c.seed==0?1:float(i%9-4)/8;}c.ref=c.init;for(int b=0;b<c.batches;b++){forward_pass(c.ref[0].data(),c.ref[3].data(),c.n,1);backward_pass(c.ref[3].data(),c.ref[2].data(),c.ref[4].data(),c.n);sgd_update(c.ref[1].data(),c.ref[4].data(),c.n,0.01f);data_prefetch(c.ref[0].data(),c.n,b+1);}for(int j=0;j<5;j++){GPU_CHECK(cudaMalloc(&c.d[j],c.n*4));prefix.insert(prefix.end(),c.init[j].begin(),c.init[j].end());}for(int q:{c.n,c.batches,c.seed,c.mode,256,256,1})prefix.push_back(q);prefix.push_back(0.01f);prefix.push_back(lo);prefix.push_back(hi);cases.push_back(c);}
auto run=[&](Case&c,std::vector<float>&out){for(int j=0;j<5;j++)GPU_CHECK(cudaMemcpy(c.d[j],c.init[j].data(),c.n*4,cudaMemcpyHostToDevice));cudaEvent_t fwd,fetch;GPU_CHECK(cudaEventCreate(&fwd));GPU_CHECK(cudaEventCreate(&fetch));int blocks=(c.n+255)/256;GPU_CHECK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int b=0;b<c.batches;b++){if(c.mode==0){forward_pass_kernel<<<blocks,256>>>(c.d[0],c.d[3],c.n,1);backward_pass_kernel<<<blocks,256>>>(c.d[3],c.d[2],c.d[4],c.n);sgd_update_kernel<<<blocks,256>>>(c.d[1],c.d[4],c.n,0.01f);data_prefetch_kernel<<<blocks,256>>>(c.d[0],c.n,b+1);}else{GPU_CHECK(cudaStreamWaitEvent(train,fetch,0));forward_pass_kernel<<<blocks,256,0,train>>>(c.d[0],c.d[3],c.n,1);GPU_CHECK(cudaEventRecord(fwd,train));backward_pass_kernel<<<blocks,256,0,train>>>(c.d[3],c.d[2],c.d[4],c.n);sgd_update_kernel<<<blocks,256,0,train>>>(c.d[1],c.d[4],c.n,0.01f);GPU_CHECK(cudaStreamWaitEvent(prefetch,fwd,0));data_prefetch_kernel<<<blocks,256,0,prefetch>>>(c.d[0],c.n,b+1);GPU_CHECK(cudaEventRecord(fetch,prefetch));}}if(c.mode==0){GPU_CHECK(cudaDeviceSynchronize());}else{GPU_CHECK(cudaStreamSynchronize(train));}double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();bool pending=false;if(c.mode==1){auto state=cudaStreamQuery(prefetch);pending=state==cudaErrorNotReady;if(state!=cudaSuccess&&state!=cudaErrorNotReady)GPU_CHECK(state);GPU_CHECK(cudaStreamSynchronize(prefetch));}GPU_CHECK(cudaDeviceSynchronize());bool ok=true;double err=0;for(int j=0;j<5;j++){std::vector<float>v(c.n);GPU_CHECK(cudaMemcpy(v.data(),c.d[j],c.n*4,cudaMemcpyDeviceToHost));out.insert(out.end(),v.begin(),v.end());for(int i=0;i<c.n;i++){ok&=std::isfinite(v[i]);err=std::max(err,double(fabsf(v[i]-c.ref[j][i])));}}ok&=err<=1e-3;GPU_CHECK(cudaEventDestroy(fwd));GPU_CHECK(cudaEventDestroy(fetch));return std::make_tuple(elapsed,ok,err,pending);};std::vector<float>tmp;for(auto&c:cases)run(c,tmp);for(int trial=1;trial<=5;trial++){auto out=prefix;double elapsed=0,err=0;bool ok=true;std::vector<bool>pending;std::cout<<"STUDY_COMPONENT_SECONDS ";for(auto&c:cases){auto[t,pass,e,pend]=run(c,out);elapsed+=t;err=std::max(err,e);ok&=pass;pending.push_back(pend);std::cout<<std::setprecision(17)<<t<<",";}std::cout<<std::endl<<"STUDY_PREFETCH_PENDING_AT_TIMER_END ";for(bool b:pending)std::cout<<(b?"true":"false")<<",";std::cout<<std::endl;std::string path="trial_"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)out.data(),out.size()*4);f.close();std::cout<<"STUDY_TRIAL {\"trial\":"<<trial<<",\"time_seconds\":"<<elapsed<<",\"correct\":"<<(ok?"true":"false")<<",\"checked_values\":"<<out.size()<<",\"max_abs_error\":"<<err<<",\"timing_region\":\"sum4_source_permode_completion_pipelines\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\""<<path<<"\",\"dtype\":\"float32\",\"count\":"<<out.size()<<",\"byte_order\":\"little\"}}"<<std::endl;if(!ok)return 2;}GPU_CHECK(cudaStreamDestroy(train));GPU_CHECK(cudaStreamDestroy(prefetch));}
